import {
  collectExtras,
  FieldConfigExtras,
  readArray,
  readBoolean,
  readConfigSource,
  readOption,
  readRecord,
  readString,
} from './config-readers';
import {
  CHOICE_ORIENTATIONS,
  CHOICE_SORTS,
  ChoiceOrientation,
  ChoiceSort,
  FIELD_INPUT_SIZES,
  FieldChoiceOption,
  FieldInputSize,
  parseChoiceOptions,
} from './field-definition-type-common.model';

/**
 * What a `RadioButton` field's `fieldConfig` JSON deserialises to.
 *
 * Read by `RadioFieldInputComponent`, written by `RadioFieldConfigComponent`. This is the one
 * config of the seven that can be *empty in a way that matters*: a radio field with no options
 * renders nothing a user can pick, so `RadioFieldConfigComponent.isValid` requires at least one
 * and the host's submit guard blocks the save.
 */
export interface RadioFieldConfig extends FieldConfigExtras {
  options: FieldChoiceOption[];
  orientation: ChoiceOrientation;
  /** What order the buttons are drawn in — see {@link sortChoiceOptions}. Applied at render time,
      so `options` above stays in the order it was authored. */
  sortChoices: ChoiceSort;
  /**
   * Offer a way back to "nothing selected".
   *
   * Radio buttons have no native way to deselect, so without this a user who picks a value by
   * mistake cannot undo it — the field goes from empty to permanently answered on the first
   * click. Worth having on any field that is not required.
   */
  allowClear: boolean;
  size: FieldInputSize;
}

export const DEFAULT_RADIO_FIELD_CONFIG: RadioFieldConfig = {
  options: [],
  orientation: 'vertical',
  sortChoices: 'none',
  allowClear: false,
  size: '',
  extra: {},
};

/** A saved radio config, defaulting every member it cannot read. */
export function parseRadioFieldConfig(
  json: string | null,
  defaults: RadioFieldConfig,
): RadioFieldConfig {
  const source = readConfigSource(json);

  if (source === null) {
    return defaults;
  }

  return {
    options: parseChoiceOptions(
      readArray(source['options']),
      defaults.options,
      readString,
      readRecord,
    ),
    orientation: readOption(source['orientation'], CHOICE_ORIENTATIONS, defaults.orientation),
    sortChoices: readOption(source['sortChoices'], CHOICE_SORTS, defaults.sortChoices),
    allowClear: readBoolean(source['allowClear'], defaults.allowClear),
    size: readOption(source['size'], FIELD_INPUT_SIZES, defaults.size),
    extra: collectExtras(source, defaults),
  };
}
