import {
  collectExtras,
  FieldConfigExtras,
  readBoolean,
  readConfigSource,
  readNullableNumber,
  readNumber,
  readOption,
  readString,
} from './config-readers';
import { FIELD_INPUT_SIZES, FieldInputSize } from './field-definition-type-common.model';

/**
 * What a `TextArea` field's `fieldConfig` JSON deserialises to.
 *
 * Read by `TextareaFieldInputComponent` and written by `TextareaFieldConfigComponent`. Kept
 * separate from `TextFieldConfig` despite the overlap: a textarea has no input type, no icons and
 * no mask, and has `rows` and `autoResize` instead. Sharing one shape would mean six members that
 * do nothing on one of the two renderers, which is how a config UI starts lying about what it
 * controls.
 */
export interface TextareaFieldConfig extends FieldConfigExtras {
  placeholder: string;
  /** Visible height in lines, before any scrolling or auto-resizing. */
  rows: number;
  /** Null means no limit. Browser-enforced as `maxlength`. */
  maxLength: number | null;
  /** Grow to fit the content as the user types, rather than scrolling within `rows`. */
  autoResize: boolean;
  size: FieldInputSize;
}

/** Matches the `rows="5"` the raw-JSON textarea this renderer replaces has always used. */
export const DEFAULT_TEXTAREA_FIELD_CONFIG: TextareaFieldConfig = {
  placeholder: '',
  rows: 5,
  maxLength: null,
  autoResize: false,
  size: '',
  extra: {},
};

/** A saved textarea config, defaulting every member it cannot read. See `parseTextFieldConfig`
    for why `defaults` is a parameter. */
export function parseTextareaFieldConfig(
  json: string | null,
  defaults: TextareaFieldConfig,
): TextareaFieldConfig {
  const source = readConfigSource(json);

  if (source === null) {
    return defaults;
  }

  return {
    placeholder: readString(source['placeholder'], defaults.placeholder),
    rows: readNumber(source['rows'], defaults.rows),
    maxLength: readNullableNumber(source['maxLength'], defaults.maxLength),
    autoResize: readBoolean(source['autoResize'], defaults.autoResize),
    size: readOption(source['size'], FIELD_INPUT_SIZES, defaults.size),
    extra: collectExtras(source, defaults),
  };
}
